#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "m²K/kW".parse::<ThermalInsulanceUnit>(),
        Ok(ThermalInsulanceUnit::SquareMeterKelvinPerKilowatt)
    );
    assert_eq!(
        format!("2.5 {}", "m²K/kW").parse::<ThermalInsulance>(),
        Ok(ThermalInsulance::new(
            2.5,
            ThermalInsulanceUnit::SquareMeterKelvinPerKilowatt
        ))
    );
    assert_eq!(
        "m²K/W".parse::<ThermalInsulanceUnit>(),
        Ok(ThermalInsulanceUnit::SquareMeterKelvinPerWatt)
    );
    assert_eq!(
        format!("2.5 {}", "m²K/W").parse::<ThermalInsulance>(),
        Ok(ThermalInsulance::new(
            2.5,
            ThermalInsulanceUnit::SquareMeterKelvinPerWatt
        ))
    );
    assert_eq!(
        "m²°C/W".parse::<ThermalInsulanceUnit>(),
        Ok(ThermalInsulanceUnit::SquareMeterDegreeCelsiusPerWatt)
    );
    assert_eq!(
        format!("2.5 {}", "m²°C/W").parse::<ThermalInsulance>(),
        Ok(ThermalInsulance::new(
            2.5,
            ThermalInsulanceUnit::SquareMeterDegreeCelsiusPerWatt
        ))
    );
    assert_eq!(
        "cm²K/W".parse::<ThermalInsulanceUnit>(),
        Ok(ThermalInsulanceUnit::SquareCentimeterKelvinPerWatt)
    );
    assert_eq!(
        format!("2.5 {}", "cm²K/W").parse::<ThermalInsulance>(),
        Ok(ThermalInsulance::new(
            2.5,
            ThermalInsulanceUnit::SquareCentimeterKelvinPerWatt
        ))
    );
    assert_eq!(
        "mm²K/W".parse::<ThermalInsulanceUnit>(),
        Ok(ThermalInsulanceUnit::SquareMillimeterKelvinPerWatt)
    );
    assert_eq!(
        format!("2.5 {}", "mm²K/W").parse::<ThermalInsulance>(),
        Ok(ThermalInsulance::new(
            2.5,
            ThermalInsulanceUnit::SquareMillimeterKelvinPerWatt
        ))
    );
    assert_eq!(
        "cm²Hr°C/kcal".parse::<ThermalInsulanceUnit>(),
        Ok(ThermalInsulanceUnit::SquareCentimeterHourDegreeCelsiusPerKilocalorie)
    );
    assert_eq!(
        format!("2.5 {}", "cm²Hr°C/kcal").parse::<ThermalInsulance>(),
        Ok(ThermalInsulance::new(
            2.5,
            ThermalInsulanceUnit::SquareCentimeterHourDegreeCelsiusPerKilocalorie
        ))
    );
    assert_eq!(
        "Hrft²°F/Btu".parse::<ThermalInsulanceUnit>(),
        Ok(ThermalInsulanceUnit::HourSquareFeetDegreeFahrenheitPerBtu)
    );
    assert_eq!(
        format!("2.5 {}", "Hrft²°F/Btu").parse::<ThermalInsulance>(),
        Ok(ThermalInsulance::new(
            2.5,
            ThermalInsulanceUnit::HourSquareFeetDegreeFahrenheitPerBtu
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<ThermalInsulance>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = ThermalInsulance::from_base(6.0);
    let b = ThermalInsulance::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = ThermalInsulance::<i64>::from_base(7);
    let b = ThermalInsulance::<i64>::from_base(2);
    assert_eq!(a + b, ThermalInsulance::from_base(9));
    assert_eq!(a % b, ThermalInsulance::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<ThermalInsulance<i64>>(),
        ThermalInsulance::from_base(9)
    );
}
